-- Auditoría individual de diferencias en enlaces de cobertura ya certificados.
-- 51 filas exactas, sin modificación a IG, legacy, lectores, versiones o deprecaciones.
BEGIN;
DO $pre$
BEGIN
 IF (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada)<>80
 OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>54
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>12
 THEN RAISE EXCEPTION 'LF_COBERTURA_AUDITORIA_BASELINE'; END IF;
END $pre$;
CREATE TEMP TABLE auditoria_51 ON COMMIT DROP AS
 SELECT (x->>'legacy_id')::int legacy_id,x->>'nucleo_codigo' nucleo_codigo,
 x->>'estado_cobertura' estado_cobertura,x->>'diferencias' diferencias,x->>'residual' residual
 FROM jsonb_array_elements('[{"legacy_id":14,"nucleo_codigo":"M4-B01","estado_cobertura":"PARCIAL","diferencias":"La legada obliga marcar ABANDONED al expirar incluso sin reanudación; el núcleo solo bloquea al intentar reanudar una sesión OTP no verificada.","residual":"Falta transición automática a ABANDONED en la expiración, independientemente de que exista reanudación."},{"legacy_id":15,"nucleo_codigo":"M4-B02","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_SES_002 exige regresar al Paso 1 sin precargar datos tras expiración; M4-B02 BLOQUEA continuar o precargar una sesión expirada y exige Paso 1.","residual":""},{"legacy_id":18,"nucleo_codigo":"M4-B03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_SES_005 inmoviliza la sesión con onboarding_completed=true; M4-B03 BLOQUEA modificaciones y deriva cambios posteriores al flujo autenticado Mi Cuenta.","residual":""},{"legacy_id":21,"nucleo_codigo":"M4-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_SEG_003 prohíbe DNI en logs, analytics, mensajes de error y headers; M4-C01 BLOQUEA exposición de ese dato en esas cuatro salidas.","residual":""},{"legacy_id":24,"nucleo_codigo":"M4-C02","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_SEG_006 prohíbe session_id en GET y admite header/cookie httpOnly; M4-C02 BLOQUEA la URL con identificador y conserva transporte autorizado.","residual":""},{"legacy_id":30,"nucleo_codigo":"M4-B04","estado_cobertura":"PARCIAL","diferencias":"La legada exige timer ordinario visible y precedencia del cooldown AUTH/OTP_EXHAUSTION_COOLDOWN_SECONDS sobre AUTH/OTP_ORDINARY_RESEND_TIMER_SECONDS al agotar AUTH/OTP_MAX_ATTEMPTS; M4-B04 bloquea reenvíos, pero no exige visibilidad del timer.","residual":"Falta presentación del timer ordinario visible y su precedencia observable en UI al agotamiento de OTP."},{"legacy_id":62,"nucleo_codigo":"M4-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_SEG_008 prohíbe otp_code en respuesta API; M4-C03 BLOQUEA respuesta si incluye el secreto y permite solo resultado de envío/verificación.","residual":""},{"legacy_id":63,"nucleo_codigo":"M4-B05","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_RL_001 exige temporizador AUTH/OTP_ORDINARY_RESEND_TIMER_SECONDS antes de habilitar reenvío; M4-B05 impide habilitación mientras timer server-side no venza.","residual":""},{"legacy_id":64,"nucleo_codigo":"M4-B06","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_RL_002 bloquea reenvío tras AUTH/OTP_MAX_RESENDS durante AUTH/OTP_RESEND_LIMIT_COOLDOWN_MINUTES; M4-B06 usa esos dos parámetros y libera después del cooldown.","residual":""},{"legacy_id":65,"nucleo_codigo":"M4-B07","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_RL_003 bloquea cambio inline al superar AUTH/PHONE_UPDATE_MAX_PER_SESSION, muestra soporte y conserva sesión; M4-B07 bloquea ese intento, cita la misma configuración y no sustituye REG_SEG_005.","residual":""},{"legacy_id":123,"nucleo_codigo":"M4-B08","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_ATQ_003 impide CAPTCHA adicional en paso OTP; M4-B08 BLOQUEA intento de presentar CAPTCHA en Paso 2 sin afectar Paso 1.","residual":""},{"legacy_id":128,"nucleo_codigo":"M4-C04","estado_cobertura":"PARCIAL","diferencias":"La legada exige además el mensaje literal «No pudimos procesar tu solicitud. Intenta nuevamente o contáctanos.»; M4-C04 solo obliga a una respuesta genérica, sin literal aprobado.","residual":"Falta imponer el copy literal uniforme aprobado para DNI registrado, bloqueado o sospechoso."},{"legacy_id":129,"nucleo_codigo":"M4-C05","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_ATQ_009 pide respuesta genérica que no revele celular registrado/bloqueado; M4-C05 bloquea exposición de existencia o estado de celular protegido.","residual":""},{"legacy_id":142,"nucleo_codigo":"M2-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_HMV_002 exige autoselección de pago único al ser única modalidad; M2-C01 exige autoselección si hay exactamente una, incluido pago único.","residual":""},{"legacy_id":143,"nucleo_codigo":"M2-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_HMV_003 exige autoselección de cuotas si es única modalidad; M2-C01 exige ese resultado y no autoselecciona si ambas están disponibles.","residual":""},{"legacy_id":144,"nucleo_codigo":"M2-C02","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_HMV_004 exige elección del usuario con pago único y cuotas; M2-C02 bloquea continuar sin elección o autoselección sin consentimiento.","residual":""},{"legacy_id":145,"nucleo_codigo":"M2-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_HMV_005 pide modalidad independiente por cada oferta activa; M2-C03 impide alterar la selección de otra oferta.","residual":""},{"legacy_id":146,"nucleo_codigo":"M2L2-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_001 pide oferta por deuda independiente; M2L2-C01 evita duplicar oferta por distintas modalidades de una deuda.","residual":""},{"legacy_id":147,"nucleo_codigo":"M2L2-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_002 agrupa pago único y cuotas en una oferta; M2L2-C01 bloquea presentarlas como ofertas diferentes.","residual":""},{"legacy_id":148,"nucleo_codigo":"M2-C04","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_003 exige modalidad dentro de modalidades_disponibles; M2-C04 bloquea mostrar modalidad no autorizada por backend de esa oferta.","residual":""},{"legacy_id":149,"nucleo_codigo":"M2-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_004 obliga autoseleccionar la modalidad única; M2-C01 exige exactamente esa conducta.","residual":""},{"legacy_id":150,"nucleo_codigo":"M2-C02","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_005 prohíbe autoselección si hay ambas modalidades; M2-C02 bloquea autoselección no consentida y exige elección antes de continuar.","residual":""},{"legacy_id":152,"nucleo_codigo":"M2-C05","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_007 bloquea checkout cuando una oferta seleccionada carece de modalidad; M2-C05 exige modalidad para cada seleccionada, no para ofertas omitidas.","residual":""},{"legacy_id":153,"nucleo_codigo":"M2-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_008 permite una o varias ofertas; M2-C03 bloquea imposición de elegir todas y permite subconjuntos.","residual":""},{"legacy_id":154,"nucleo_codigo":"M2-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_OFR_009 exige modalidad propia por oferta; M2-C03 bloquea alterar modalidad de otra oferta.","residual":""},{"legacy_id":155,"nucleo_codigo":"M1-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_CHK_001 exige resumen consolidado único de ofertas/modalidades; M1-C01 bloquea resumen incompleto, múltiple o incongruente.","residual":""},{"legacy_id":156,"nucleo_codigo":"REG_CHK_002","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_CHK_002 suma montos de modalidades elegidas; REG_CHK_002 v2 calcula monto_total por oferta seleccionada sin mezclar comisiones.","residual":""},{"legacy_id":171,"nucleo_codigo":"M2L2-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_UX_002 distingue card sin seleccionar/seleccionada/vencida, colores y badge; M2L2-C03 bloquea render que no corresponda al estado server-side, con borde y badge de vencida.","residual":""},{"legacy_id":172,"nucleo_codigo":"M2L2-C04","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_UX_003 exige copy sobre ofertas no seleccionadas y ocultarlo si todas; M2L2-C04 comprueba el texto literal según la selección.","residual":""},{"legacy_id":210,"nucleo_codigo":"REG_CHK_006","estado_cobertura":"PARCIAL","diferencias":"La legada cita porcentajes históricos en duro y legibilidad antes de confirmar; REG_CHK_006 evita ocultar comisiones y remite importes a configuración del aliado. No valida tamaño tipográfico ni fórmula de precio.","residual":"Falta controlar legibilidad no reducida (texto pequeño) en presentación, además de existencia de comisión."},{"legacy_id":211,"nucleo_codigo":"REG_CHK_007","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_CHK_007 prohíbe editar selección dentro de confirmación; v3 BLOQUEA la modificación directa, permite Volver a selección antes de pagar y mantiene inmovilidad tras envío no terminal.","residual":""},{"legacy_id":229,"nucleo_codigo":"M1-C04","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_NIU_005 exige probar el flujo de checkout en sandbox y separar credenciales; M1-C04 impide habilitación productiva sin certificación de sandbox ni evidencia de segregación.","residual":""},{"legacy_id":244,"nucleo_codigo":"M2L2-C06","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_MOD_005 prioriza la primera cuota del día frente al total del plan; M2L2-C06 bloquea cuando no está visible/destacada respecto del total.","residual":""},{"legacy_id":259,"nucleo_codigo":"M2-C06","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_CUO_009 bloquea Continuar sin fecha de débito en Paso3; M2-C06 bloquea esa transición hasta seleccionar fecha.","residual":""},{"legacy_id":276,"nucleo_codigo":"REG_CHK_013","estado_cobertura":"PARCIAL","diferencias":"La legada obliga a mostrar el checkbox con el copy literal y bloquear Pagar; REG_CHK_013 comprueba autorización y evidencia cuando el medio realmente requiere débito automático, sin exigir ese copy literal.","residual":"Falta el texto visible de consentimiento en el checkbox y su correspondencia con el botón Pagar."},{"legacy_id":288,"nucleo_codigo":"REG_CHK_013","estado_cobertura":"PARCIAL","diferencias":"La legada requiere checkbox de texto literal de autorización de cobro automático; REG_CHK_013 exige consentimiento explícito verificado y lo condiciona a que el medio requiera recurrencia.","residual":"Falta conservar el copy literal del checkbox en cobros automáticos que requieren autorización."},{"legacy_id":317,"nucleo_codigo":"M3-C01","estado_cobertura":"PARCIAL","diferencias":"La legada permite referencia canónica en overlays, confirmaciones, documentos y notificaciones; M3-C01 bloquea referencia inventada en checkout, confirmación o documento, pero no menciona notificaciones explícitamente.","residual":"Falta garantía de referencia canónica al mostrar notificaciones y overlays fuera del checkout."},{"legacy_id":382,"nucleo_codigo":"M2L2-C07","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: UX-HOME-CAPABILITY-04 sustituye simulación hipotética por Revisar tu oferta, si la tenemos disponible; M2L2-C07 prohíbe promesa ficticia y conserva ese copy.","residual":""},{"legacy_id":396,"nucleo_codigo":"M4C-C01","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-AUTH-001 deniega acciones operativas sin usuario, empresa, permiso, recurso y transición autorizados; M4C-C01 bloquea precisamente el intento sin autorización server-side y excluye pre-auth.","residual":""},{"legacy_id":397,"nucleo_codigo":"M4C-C02","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-AUTH-002 restringe consultas o mutaciones al conjunto de empresas autorizado por servidor; M4C-C02 bloquea si company_id no pertenece al conjunto, también para multiempresa.","residual":""},{"legacy_id":402,"nucleo_codigo":"M4C-C03","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-STORAGE-002 exige verificar extensión, MIME, tamaño, checksum, plantilla y malware; M4C-C03 bloquea el procesamiento si falta cualquiera de las seis verificaciones.","residual":""},{"legacy_id":426,"nucleo_codigo":"M4C-C05","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-AUTH-005 prohíbe contraseña en tablas, logs, analytics y replay; M4C-C05 bloquea persistencia o transmisión fuera del proveedor de autenticación.","residual":""},{"legacy_id":428,"nucleo_codigo":"M4C-C06","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-AUTH-007 permite mostrar/ocultar contraseña sin cambiar valor o telemetría; M4C-C06 bloquea esas alteraciones.","residual":""},{"legacy_id":430,"nucleo_codigo":"M4C-C07","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-AUTH-011 permite gestores, pegado y autocomplete; M4C-C07 bloquea impedirlos o desmontar el campo de contraseña.","residual":""},{"legacy_id":456,"nucleo_codigo":"M4-C06","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_AUTH_PHONE_OWNERSHIP_001 establece OTP de celular no acredita identidad civil ni permite reasignación; M4-C06 bloquea esa atribución sin identidad/recuperación.","residual":""},{"legacy_id":492,"nucleo_codigo":"M4-C07","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_ONB003_DNI_CLIENT_STORAGE_001 prohíbe DNI en storage/URL/analytics/replay/caché; M4-C07 bloquea las mismas rutas en ONB_003.","residual":""},{"legacy_id":499,"nucleo_codigo":"M4-C08","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_ONB003_ANTI_ENUM_EXPLICIT_001 prohíbe flags de existencia de DNI; M4-C08 bloquea exposiciones explícitas en respuestas ONB_003.","residual":""},{"legacy_id":523,"nucleo_codigo":"REG_CHK_004","estado_cobertura":"PARCIAL","diferencias":"La legada exige normalizar todo outcome de proveedor, incluidos ERROR, timeout y callback perdido, a PAYMENT_PENDING_CONFIRMATION si el intento pudo llegar; REG_CHK_004 únicamente consume outcomes normalizados para autorizar reintentos.","residual":"Falta generar outcome seguro mediante normalización autoritativa de respuestas crudas del proveedor y casos ambiguos."},{"legacy_id":539,"nucleo_codigo":"REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001 prohíbe que Ya escaneé confirme pago sin backend; regla núcleo del mismo código bloquea avanzar sin evidencia QR de misma referencia.","residual":""},{"legacy_id":604,"nucleo_codigo":"M3-C04","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-PAYMENT-FLOW-001 requiere PAYMENT_CONFIRMED server-side y atribución por empresa/deuda/oferta para asignación/liquidación; M3-C04 bloquea el resto, incluido PAYMENT_PENDING_CONFIRMATION.","residual":""},{"legacy_id":607,"nucleo_codigo":"M3-C05","estado_cobertura":"REEMPLAZADA","diferencias":"Sin diferencias de intención verificadas: B2B-RULE-RECONCILIATION-001 exige contraste financiero independiente y excepciones trazables; M3-C05 bloquea declarar CONCILIADO si falta evidencia o diferencia justificada.","residual":""}]'::jsonb) x;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM auditoria_51)<>51
 OR EXISTS(SELECT 1 FROM auditoria_51 x WHERE NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c
 WHERE c.legacy_id=x.legacy_id AND c.nucleo_codigo=x.nucleo_codigo AND c.estado_cobertura='REEMPLAZADA'
 AND c.diferencias='La regla legada es descriptiva del resultado; la regla del núcleo lo expresa como condición/efecto verificable para su mismo ámbito, sin acreditar binding runtime. No cambia la intención sustantiva.'))
 OR EXISTS(SELECT 1 FROM auditoria_51 x WHERE length(x.diferencias)<85)
 THEN RAISE EXCEPTION 'LF_COBERTURA_AUDITORIA_SOURCE_DRIFT'; END IF;
END $verify$;
UPDATE lf_ops.lf_nucleo_cobertura_legada c SET
 estado_cobertura=x.estado_cobertura,diferencias=x.diferencias,
 evidencia=jsonb_set(c.evidencia,'{residual}',to_jsonb(x.residual),true),
 revisado_por='GPT-6 contraste individual origen y nucleo 2026-11-23',fecha=now()
FROM auditoria_51 x
WHERE c.legacy_id=x.legacy_id AND c.nucleo_codigo=x.nucleo_codigo;
SAVEPOINT audit_negativo;
DO $negative$ DECLARE ok boolean:=false; BEGIN
 BEGIN
 UPDATE lf_ops.lf_nucleo_cobertura_legada SET hash_paquete=repeat('0',64)
 WHERE legacy_id=65 AND nucleo_codigo='M4-B07';
 EXCEPTION WHEN check_violation THEN ok=SQLERRM='LF_COBERTURA_HASH_PAQUETE_INVALIDO'; END;
 IF NOT ok THEN RAISE EXCEPTION 'LF_AUDIT_HASH_NEGATIVE_FAILED'; END IF;
 ok:=false;
 BEGIN
 UPDATE lf_ops.lf_nucleo_cobertura_legada SET estado_cobertura='REEMPLAZADA'
 WHERE legacy_id=30 AND nucleo_codigo='M4-B04';
 EXCEPTION WHEN check_violation THEN ok=SQLERRM='LF_COBERTURA_RESIDUAL_NO_CUBIERTO'; END;
 IF NOT ok THEN RAISE EXCEPTION 'LF_AUDIT_RESIDUAL_NEGATIVE_FAILED'; END IF;
 RAISE NOTICE 'LF_AUDIT_NEGATIVOS_PASS';
END $negative$;
ROLLBACK TO SAVEPOINT audit_negativo;
DO $final$ DECLARE n int; BEGIN
 SELECT count(distinct legacy_id) INTO n FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF n<>46
 OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='PARCIAL')<>34
 OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada WHERE diferencias LIKE 'La regla legada es descriptiva%')<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 THEN RAISE EXCEPTION 'LF_AUDIT_FINAL_COUNTS:%',n; END IF;
 RAISE NOTICE 'LF_AUDIT_FINAL_PASS replaced=% partial_rows=34',n;
END $final$;
COMMIT;